#include <iostream>
using namespace std;

class TaiKhoan {
    double soDu = 0;
public:
    void napTien(double t) { if (t > 0) soDu += t; }
    double getSoDu() { return soDu; }
};

int main() {
    TaiKhoan tk;
    tk.napTien(500);
    tk.napTien(300);
    cout << tk.getSoDu() << endl;
    return 0;
}
